// Package emoji resolves :shortcode: tokens to unicode emoji, using the same
// dataset the web client's picker ships (data.json is a copy of
// web/src/util/emoji/data.json).
package emoji

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"
	"sync"

	"go.mau.fi/util/variationselector"
)

//go:embed data.json
var rawData []byte

// keywords.json is generated by gen_keywords.py (emojilib + emojibase).
//
//go:embed keywords.json
var rawKeywords []byte

type entry struct {
	Unicode    string   `json:"u"`
	Category   int      `json:"c"`
	Title      string   `json:"t"`
	Name       string   `json:"n"`
	Shortcodes []string `json:"s"`
}

// Info is one emoji with everything search and the picker show.
type Info struct {
	Emoji     string
	Shortcode string
	Title     string
	Keywords  []string
	codes     []string
}

// Category is a picker tab: its emoji in the standard order.
type Category struct {
	Name   string
	Emojis []*Info
}

var (
	once        sync.Once
	byShortcode map[string]string
	shortcodes  []string
	all         []*Info
	byUnicode   map[string]*Info
	categories  []Category
)

func load() {
	once.Do(func() {
		var data struct {
			Emojis     []entry  `json:"e"`
			Categories []string `json:"c"`
		}
		if err := json.Unmarshal(rawData, &data); err != nil {
			byShortcode = map[string]string{}
			return
		}
		var keywords map[string][]string
		_ = json.Unmarshal(rawKeywords, &keywords)
		byUnicode = make(map[string]*Info, len(data.Emojis))
		catIndex := map[int]int{}
		for _, e := range data.Emojis {
			key := variationselector.Remove(e.Unicode)
			info := &Info{Emoji: e.Unicode, Shortcode: e.Name, Title: e.Title, Keywords: keywords[key]}
			for _, code := range append([]string{e.Name}, e.Shortcodes...) {
				if code = strings.ToLower(code); code != "" {
					info.codes = append(info.codes, code)
				}
			}
			all = append(all, info)
			byUnicode[key] = info
			if e.Category < 0 || e.Category >= len(data.Categories) || data.Categories[e.Category] == "Component" {
				continue
			}
			idx, ok := catIndex[e.Category]
			if !ok {
				idx = len(categories)
				catIndex[e.Category] = idx
				categories = append(categories, Category{Name: data.Categories[e.Category]})
			}
			categories[idx].Emojis = append(categories[idx].Emojis, info)
		}
		byShortcode = make(map[string]string, len(data.Emojis)*2)
		for _, e := range data.Emojis {
			for _, code := range append([]string{e.Name}, e.Shortcodes...) {
				code = strings.ToLower(code)
				if code == "" {
					continue
				}
				if _, exists := byShortcode[code]; !exists {
					byShortcode[code] = e.Unicode
				}
			}
		}
		shortcodes = make([]string, 0, len(byShortcode))
		for code := range byShortcode {
			shortcodes = append(shortcodes, code)
		}
		sort.Strings(shortcodes)
	})
}

// Get returns the emoji for a shortcode (without colons), or "".
func Get(shortcode string) string {
	load()
	return byShortcode[strings.ToLower(shortcode)]
}

// Match is one completion candidate; Keyword is set when a search matched
// a meaning word ("awkward") rather than the shortcode.
type Match struct {
	Shortcode string
	Emoji     string
	Keyword   string
}

// Categories returns the picker tabs in the standard order, skin tones left out.
func Categories() []Category {
	load()
	return categories
}

// Lookup finds an emoji's info, with or without variation selectors.
func Lookup(e string) *Info {
	load()
	return byUnicode[variationselector.Remove(e)]
}

// Complete returns up to limit shortcodes starting with the given prefix.
func Complete(prefix string, limit int) []Match {
	load()
	prefix = strings.ToLower(prefix)
	var matches []Match
	idx := sort.SearchStrings(shortcodes, prefix)
	for ; idx < len(shortcodes) && len(matches) < limit; idx++ {
		if !strings.HasPrefix(shortcodes[idx], prefix) {
			break
		}
		matches = append(matches, Match{Shortcode: shortcodes[idx], Emoji: byShortcode[shortcodes[idx]]})
	}
	return matches
}

// Search finds emoji by shortcode or meaning, best first: exact shortcode,
// shortcode prefix, exact keyword ("awk" for 😬), shortcode substring, then
// keyword or title prefix. Ties keep the standard emoji order.
func Search(query string, limit int) []Match {
	load()
	query = strings.ToLower(strings.TrimSpace(query))
	if query == "" {
		return nil
	}
	type ranked struct {
		Match
		tier, idx int
	}
	var found []ranked
	for idx, info := range all {
		best := ranked{tier: 99, idx: idx}
		try := func(tier int, code, keyword string) {
			if tier < best.tier {
				best.tier, best.Match = tier, Match{Shortcode: code, Emoji: info.Emoji, Keyword: keyword}
			}
		}
		for _, code := range info.codes {
			switch {
			case code == query:
				try(0, code, "")
			case strings.HasPrefix(code, query):
				try(1, code, "")
			case strings.Contains(code, query):
				try(3, code, "")
			}
		}
		for _, kw := range info.Keywords {
			switch {
			case kw == query:
				try(2, info.Shortcode, kw)
			case strings.HasPrefix(kw, query):
				try(4, info.Shortcode, kw)
			}
		}
		for _, word := range strings.Fields(strings.ToLower(info.Title)) {
			if strings.HasPrefix(word, query) {
				try(4, info.Shortcode, word)
			}
		}
		if best.tier < 99 {
			found = append(found, best)
		}
	}
	sort.SliceStable(found, func(i, j int) bool {
		a, b := found[i], found[j]
		if a.tier != b.tier {
			return a.tier < b.tier
		}
		// Among shortcode matches the shorter name wins: fi gives fire, not fight_cloud.
		if a.Keyword == "" && b.Keyword == "" && len(a.Shortcode) != len(b.Shortcode) {
			return len(a.Shortcode) < len(b.Shortcode)
		}
		return a.idx < b.idx
	})
	out := make([]Match, 0, min(limit, len(found)))
	for _, r := range found {
		if len(out) == limit {
			break
		}
		out = append(out, r.Match)
	}
	return out
}

func isShortcodeChar(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' ||
		c == '_' || c == '+' || c == '-'
}

// IsValidToken reports whether s could be the start of a shortcode: non-empty
// and made only of shortcode characters.
func IsValidToken(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if !isShortcodeChar(s[i]) {
			return false
		}
	}
	return true
}

// Replace substitutes every :shortcode: in text with its emoji, with the
// variation selectors Matrix expects. Unknown shortcodes are left alone.
func Replace(text string) string {
	load()
	var out strings.Builder
	for {
		start := strings.IndexByte(text, ':')
		if start == -1 {
			break
		}
		end := start + 1
		for end < len(text) && isShortcodeChar(text[end]) {
			end++
		}
		if end < len(text) && text[end] == ':' && end > start+1 {
			if emoji := byShortcode[strings.ToLower(text[start+1:end])]; emoji != "" {
				out.WriteString(text[:start])
				out.WriteString(variationselector.Add(emoji))
				text = text[end+1:]
				continue
			}
		}
		out.WriteString(text[:end])
		text = text[end:]
	}
	out.WriteString(text)
	return out.String()
}
